namespace WebScan.Contracts;

/// <summary>
/// Partial or final results of a job, sent to <c>POST /api/agents/jobs/{jobId}/results</c>.
/// Idempotent: the server stores each <see cref="BatchId"/> once; re-sending returns 200 with <c>duplicate=true</c>.
/// Bodies may be gzip-compressed (<c>Content-Encoding: gzip</c>).
/// </summary>
public sealed record ScanResultBatch
{
    /// <summary>Generated by the agent before the first send attempt and reused on every retry.</summary>
    public required Guid BatchId { get; init; }

    public required Guid JobId { get; init; }
    public required Guid LeaseId { get; init; }

    /// <summary>0-based, monotonically increasing per job.</summary>
    public required int Sequence { get; init; }

    public required DateTimeOffset CreatedAt { get; init; }

    /// <summary>Max 5000 observations per batch.</summary>
    public required IReadOnlyList<DiscoveryObservation> Observations { get; init; }

    public JobProgress? Progress { get; init; }

    public const int MaxObservations = 5000;
}

public sealed record JobProgress
{
    public long TargetsTotal { get; init; }
    public long TargetsCompleted { get; init; }

    /// <summary>0–100.</summary>
    public double Percent { get; init; }

    public string? Message { get; init; }
}

public sealed record ResultBatchAck
{
    public required Guid BatchId { get; init; }
    public required bool Accepted { get; init; }
    public bool Duplicate { get; init; }
    public int ObservationsAccepted { get; init; }
}

/// <summary><c>POST /api/agents/jobs/{jobId}/heartbeat</c>: extends the lease and reports progress.</summary>
public sealed record JobHeartbeatRequest
{
    public required Guid LeaseId { get; init; }
    public JobProgress? Progress { get; init; }
}

public sealed record JobHeartbeatResponse
{
    public required DateTimeOffset LeaseExpiresAt { get; init; }

    /// <summary>When true the agent must kill the tool, send buffered results and call <c>/fail</c> with <see cref="JobFailureReason.Cancelled"/>.</summary>
    public bool CancelRequested { get; init; }
}

/// <summary><c>POST /api/agents/jobs/{jobId}/complete</c>.</summary>
public sealed record JobCompletionRequest
{
    public required Guid LeaseId { get; init; }

    /// <summary>Number of result batches sent for this lease (server verifies it has them all).</summary>
    public required int TotalBatches { get; init; }

    public required JobCoverage Coverage { get; init; }
    public required ToolRunInfo ToolRun { get; init; }
}

/// <summary>
/// Which targets were actually covered. The server must not infer "host gone" for targets that were not covered
/// (window expired, tool crashed mid-way).
/// </summary>
public sealed record JobCoverage
{
    /// <summary>True when every target of the job was scanned to completion.</summary>
    public required bool Complete { get; init; }

    /// <summary>When <see cref="Complete"/> is false: targets (host entries or "addr:port") that were NOT covered.</summary>
    public IReadOnlyList<string> UncoveredTargets { get; init; } = [];
}

public sealed record ToolRunInfo
{
    public required string ToolId { get; init; }
    public string? ToolVersion { get; init; }
    public int? ExitCode { get; init; }
    public required long DurationMs { get; init; }

    /// <summary>Last lines of stderr (max 4 KB, masked).</summary>
    public string? StderrTail { get; init; }
}

public enum JobFailureReason
{
    ToolError,
    Timeout,
    Cancelled,
    WindowExpired,
    InvalidJob,
    ToolNotAvailable,
    AgentShutdown,
    Internal,
}

/// <summary><c>POST /api/agents/jobs/{jobId}/fail</c>.</summary>
public sealed record JobFailureRequest
{
    public required Guid LeaseId { get; init; }
    public required JobFailureReason Reason { get; init; }
    public string? Message { get; init; }

    /// <summary>Whether the server may retry the job (false for InvalidJob).</summary>
    public bool Retryable { get; init; } = true;

    public int TotalBatches { get; init; }
    public JobCoverage? Coverage { get; init; }
    public ToolRunInfo? ToolRun { get; init; }
}

/// <summary><c>POST /api/agents/jobs/claim</c>.</summary>
public sealed record JobClaimRequest
{
    /// <summary>How many jobs the agent can start now (its free slots).</summary>
    public required int MaxJobs { get; init; }

    /// <summary>Optional: interfaces that currently have free capacity (null = any).</summary>
    public IReadOnlyList<string>? Interfaces { get; init; }
}

public sealed record JobClaimResponse
{
    public required IReadOnlyList<JobAssignment> Assignments { get; init; }

    /// <summary>Hint for the next poll when nothing was assigned.</summary>
    public int NextPollSeconds { get; init; } = 5;
}

/// <summary>Agent API routes (relative to server base URL).</summary>
public static class AgentApiRoutes
{
    public const string Register = "/api/agents/register";
    public const string Heartbeat = "/api/agents/heartbeat";
    public const string RotateCredentials = "/api/agents/credentials/rotate";
    public const string Claim = "/api/agents/jobs/claim";
    public static string JobHeartbeat(Guid jobId) => $"/api/agents/jobs/{jobId}/heartbeat";
    public static string JobResults(Guid jobId) => $"/api/agents/jobs/{jobId}/results";
    public static string JobComplete(Guid jobId) => $"/api/agents/jobs/{jobId}/complete";
    public static string JobFail(Guid jobId) => $"/api/agents/jobs/{jobId}/fail";

    public const string EnrollmentTokenHeader = "X-Enrollment-Token";

    /// <summary>Authorization scheme name: <c>Authorization: Agent {agentId}:{secret}</c>.</summary>
    public const string AuthorizationScheme = "Agent";
}
